// Build an HTML scorecard table from the ISC webhook payload.
// suppliers is a JSON array of { name, tier } objects.
const suppliers = JSON.parse(inputData.suppliers || '[]');
const month = inputData.month || new Date().toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
const userName = inputData.userName || '';

const rows = suppliers.map(s =>
  `<tr>
    <td style='padding:8px 12px;border:1px solid #e2e8f0'>${s.name}</td>
    <td style='padding:8px 12px;border:1px solid #e2e8f0'>${s.tier}</td>
  </tr>`
).join('');

const html = `
<h2 style='font-family:sans-serif;color:#1e293b'>Monthly Supplier Scorecard — ${month}</h2>
<p style='font-family:sans-serif;color:#64748b'>Hi ${userName}, here is your supplier scorecard for ${month}.</p>
<table style='border-collapse:collapse;width:100%;font-family:sans-serif;font-size:13px'>
  <thead>
    <tr style='background:#f1f5f9'>
      <th style='padding:8px 12px;border:1px solid #e2e8f0;text-align:left'>Supplier</th>
      <th style='padding:8px 12px;border:1px solid #e2e8f0;text-align:left'>Tier</th>
    </tr>
  </thead>
  <tbody>${rows}</tbody>
</table>
<br/>
<p style='font-family:sans-serif'><a href='https://YOUR_ISC_DOMAIN/'>→ View full scorecard in ISC</a></p>
`;

return { html, subject: `Monthly Supplier Scorecard — ${month}` };
